package com.thakur.employee.security; import jakarta.servlet.*;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.userdetails.*;import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.*; @Component @RequiredArgsConstructor public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;private final CustomUserDetailsService users;protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);try{String email=jwt.username(t);if(SecurityContextHolder.getContext().getAuthentication()==null){UserDetails u=users.loadUserByUsername(email);if(jwt.valid(t,u.getUsername())){var a=new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities());a.setDetails(new WebAuthenticationDetailsSource().buildDetails(req));SecurityContextHolder.getContext().setAuthentication(a);}}}catch(Exception ignored){}}chain.doFilter(req,res);}}
